Ui.Script:
-- ── Strings (the shipped enUS GlobalStrings.lua values, quoted as data) ───────────────── local DUEL_REQUESTED = "%s has challenged you to a duel." -- l.957 local DUEL_OUTOFBOUNDS_TIMER = "Exiting duel area, you will forfeit in %d %s." -- l.956 local ACCEPT = "Accept" local DECLINE = "Decline"
-- ── The challenge dialog (spec: StaticPopup.lua l.1103-1116) ──────────────────────────── -- Written scalars-first, handlers-last: what the dialog IS, then what answering it does. -- -- No accept-guard flag (unlike PARTY_INVITE): the entry declines only on an explicit -- OnCancel, so a timeout or an override hides it WITHOUT sending anything. That is not an -- oversight to "fix" — the server's own 60 s is not a thing either; an unanswered challenge -- simply sits until one side acts. StaticPopupDialogs["DUEL_REQUESTED"] = { text = DUEL_REQUESTED, button1 = ACCEPT, button2 = DECLINE, sound = "igPlayerInvite", timeout = 60, hideOnEscape = 1, -- The two buttons are the two replies. ESC arrives here as well — hideOnEscape routes -- an escape through OnCancel — so backing out and declining are deliberately one path. OnAccept = function() AcceptDuel() end, OnCancel = function() CancelDuel() end, }
-- ── The out-of-bounds warning (spec: StaticPopup.lua l.1117-1120) ─────────────────────── -- Two fields and nothing else: no buttons, because there is nothing to answer, and no -- text of its own — the engine's countdown branch writes it every tick. StaticPopupDialogs["DUEL_OUTOFBOUNDS"] = { text = DUEL_OUTOFBOUNDS_TIMER, timeout = 10, }
-- ── The duel event arms (spec: UIParent.lua l.378-393) ────────────────────────────────── function BenillaDuelDriver_OnEvent() if event == "DUEL_REQUESTED" then StaticPopup_Show("DUEL_REQUESTED", arg1) elseif event == "DUEL_OUTOFBOUNDS" then StaticPopup_Show("DUEL_OUTOFBOUNDS") elseif event == "DUEL_INBOUNDS" then StaticPopup_Hide("DUEL_OUTOFBOUNDS") elseif event == "DUEL_FINISHED" then -- Both, unconditionally: a duel that ends while the challenge popup is still up -- (the other side cancelled first) must not leave it there. StaticPopup_Hide("DUEL_REQUESTED") StaticPopup_Hide("DUEL_OUTOFBOUNDS") end end
